UPDATE after_sale_exchange_returns
SET return_way = #{returnWay}, return_time_slot = #{returnTimeSlot}, return_at = #{returnAt}, updated_at = #{updatedAt}
WHERE after_sale_id = #{afterSaleId} AND shop_id = #{shopId} AND is_deleted = 0

UPDATE after_sale_exchange_returns
SET ${column} = #{now}, updated_at = #{now}
WHERE after_sale_id = #{afterSaleId} AND shop_id = #{shopId} AND is_deleted = 0

UPDATE after_sale_exchange_returns
SET is_deleted = 1, updated_at = #{now}
WHERE after_sale_id = #{afterSaleId} AND shop_id = #{shopId}
